-- Global capture learning. Only label, score bucket and vote; user id only for rate limiting. No client can read rows.
-- One statement per line (the Supabase editor on phones adds brackets to multi-line pastes). Run once.
create table if not exists public.capture_votes (id bigserial primary key, user_id uuid not null references auth.users(id) on delete cascade, label text not null check (char_length(label) between 1 and 60), bucket text check (bucket in ('0.2-0.4','0.4-0.6','0.6-0.8','0.8+')), vote smallint not null check (vote in (1,-1)), created_at timestamptz not null default now());
alter table public.capture_votes enable row level security;
create index if not exists capture_votes_user_time on public.capture_votes (user_id, created_at);
create or replace function public.capture_vote(p_label text, p_bucket text, p_vote int) returns boolean language plpgsql security definer set search_path = public as $$ declare u uuid := auth.uid(); begin if u is null or coalesce(trim(p_label), '') = '' then return false; end if; if (select count(*) from capture_votes where user_id = u and created_at > now() - interval '1 hour') >= 120 then return false; end if; insert into capture_votes(user_id, label, bucket, vote) values (u, left(trim(p_label), 60), case when p_bucket in ('0.2-0.4','0.4-0.6','0.6-0.8','0.8+') then p_bucket else null end, case when p_vote > 0 then 1 else -1 end); return true; end $$;
create or replace function public.capture_votes_summary() returns table(label text, up int, down int, multiplier real) language sql security definer set search_path = public as $$ select v.label, (count(*) filter (where v.vote = 1))::int, (count(*) filter (where v.vote = -1))::int, (case when count(*) < 200 then 1 when (count(*) filter (where v.vote = -1))::real / count(*) >= 0.7 then 1 + 0.15 * (1 + (count(*) - 200) / 200) when (count(*) filter (where v.vote = 1))::real / count(*) >= 0.75 then greatest(0, 1 - 0.10 * (1 + (count(*) - 200) / 200)) else 1 end)::real from capture_votes v group by v.label $$;
revoke all on function public.capture_vote(text, text, int), public.capture_votes_summary() from public, anon;
grant execute on function public.capture_vote(text, text, int), public.capture_votes_summary() to authenticated;
